# Try flood-fill diffusion: 5 spreads to adjacent 0s (one step)
def flood_one_step(grid):
    # Create output as copy
    output = [row[:] for row in grid]

    # Find all 5s
    five_pos = set()
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == 5:
                five_pos.add((r,c))

    # Spread to adjacent 0s (one step, 4-directional)
    for r, c in five_pos:
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                if grid[nr][nc] == 0:
                    output[nr][nc] = 5

    return output

