# Let me try a more conservative 0→6: only where 0 is surrounded by 5s diagonally
def careful_0_6(grid):
    output = [row[:] for row in grid]

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == 0:
                # Count diagonal 5s
                diag5s = 0
                for dr, dc in [(-1,-1), (-1,1), (1,-1), (1,1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                        if grid[nr][nc] == 5:
                            diag5s += 1

                # Also count non-diagonal 5 neighbors
                neigh5s = 0
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                        if grid[nr][nc] == 5:
                            neigh5s += 1

                # Apply rule: if diag5s >= 2 OR (neigh5s >= 4 and diag5s >= 3) 
                if diag5s >= 3 or (diag5s >= 2 and neigh5s >= 5):
                    if output[r][c] != 1:  # Don't overwrite ones
                        output[r][c] = 6

    return output

